local shhttp
do
        -- [patch v2] robust http function detection. rawget(getfenv(), ...) can
        -- miss globals that executors mount through environment metatables
        -- (Delta exposes plain `request` / `http_request` globals), so every
        -- known alias is probed in order.
        local picked
        local probes = {
                function() return rawget(getfenv(), "request") end,
                function() return request end,
                function() return http_request end,
                function() return syn and syn.request end,
                function() return http and http.request end,
                function() return (type(http) == "function") and http or nil end,
                function() return fluxus and fluxus.request end,
                function() return getgenv and getgenv().request end,
                function() return getgenv and getgenv().http_request end,
        }
        for _, probe in ipairs(probes) do
                local ok, fn = pcall(probe)
                if ok and type(fn) == "function" then
                        picked = fn
                        break
                end
        end
        shhttp = picked
end

if type(shhttp) ~= "function" then
        warn("[loader] no http request function found in this executor")
        shhttp = function()
                return nil
        end
end

