-- [patch v3] =====================================================================
-- EMBEDDED OFFLINE DATA: all libraries and assets are inside this file.
-- This build performs ZERO network requests (no key server, no library host)
-- and works even on executors that have no request/http function at all.
-- ================================================================================
local EMBED_B64, EMBED_RAW, EMBED_MANIFEST, EMBED_CACHE, EMBED_MAPS = {}, {}, {}, {}, nil

local function embedB64Dec(s)
        local abc = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
        local lut, out, n, acc, bits = {}, {}, 0, 0, 0

        for i = 1, #abc do
                lut[string.sub(abc, i, i)] = i - 1
        end

        for i = 1, #s do
                local v = lut[string.sub(s, i, i)]

                if v then
                        acc = acc * 64 + v
                        bits = bits + 6

                        if bits >= 8 then
                                bits = bits - 8
                                local div = 2 ^ bits
                                local byte = math.floor(acc / div)
                                acc = acc - byte * div
                                n = n + 1
                                out[n] = string.char(byte % 256)
                        end
                end
        end

        return table.concat(out)
end

-- decode-once accessor for embedded asset bytes
local function embedData(name)
        if type(name) ~= "string" then
                return nil
        end

        local hit = EMBED_CACHE[name]

        if hit then
                return hit
        end

        local raw = EMBED_RAW[name]

        if raw == nil then
                local enc = EMBED_B64[name]

                if enc == nil then
                        return nil
                end

                raw = embedB64Dec(enc)
        end

        EMBED_CACHE[name] = raw

        return raw
end

