                for y = 0, th - 1 do
                        local y0 = floor(y * h / th)
                        local y1 = floor((y + 1) * h / th) - 1
                        if y1 < y0 then y1 = y0 end

                        rn = rn + 1
                        raw[rn] = 0

                        for x = 0, tw - 1 do
                                local x0 = floor(x * w / tw)
                                local x1 = floor((x + 1) * w / tw) - 1
                                if x1 < x0 then x1 = x0 end

