        local R6_LEFT = CFrame.new(0, 0, 0, 0, 0, -1, 0, 1, 0, 1, 0, 0)
        local R6_RIGHT = CFrame.new(0, 0, 0, 0, 0, 1, 0, 1, 0, -1, 0, 0)
        local R6_GRIP = CFrame.new(0, -0.85, 0)
        local GRIP_REACH = 6

        local R6_SIZES = {
