        pref:button({
                name = "telegram",
                icon = "send",
                callback = function()
                        pcall(function()
                                setclipboard("https://t.me/shitarouse")
                                __Logging.new("107339085791087", 'copied invite to gay party', 5)
                        end)
                end,
